const fs = await tools.Read({ file_path: '/private/tmp/pcd-sbx-qwen-4-max-2kcglmhd/work/index.html' });
const html = fs.content;
// extract inline script (the second <script> block, without src)
const m = html.match(/<script>\n([\s\S]*?)<\/script>/);
if (!m) return 'NO INLINE SCRIPT FOUND';
const src = m[1];
// 1) parse check
try { new Function(src); text('PARSE OK, inline script length=' + src.length); }
catch (e) { return 'PARSE ERROR: ' + e.message; }

// 2) check forbidden APIs / external refs
const bad = [];
if (/Math\.random/.test(src)) bad.push('Math.random');
if (/fetch\(|XMLHttpRequest|WebSocket|TextureLoader/.test(src)) bad.push('network API');
if (/SRGBColorSpace/.test(src)) bad.push('SRGBColorSpace');
if (/Date\.now/.test(src)) bad.push('Date.now');
const extRefs = html.match(/https?:\/\/[^"'\s)]+/g) || [];
text('external refs: ' + JSON.stringify(extRefs));
text('forbidden: ' + (bad.length ? bad.join(',') : 'none'));

// 3) DOM contract: canonical elements present, no extra visible elements
const ids = ['stage','countdown','dock','btn-refire','btn-toggle','icon-pause','icon-play','speed-group','scrubber'];
for (const id of ids) if (!html.includes('id="' + id + '"')) text('MISSING ID: ' + id);
const bodyMatch = html.match(/<body>([\s\S]*?)<script/);
const elCount = (bodyMatch[1].match(/<(div|button|span|input|canvas|svg|path|rect)\b/g) || []).length;
text('body element tags before scripts: ' + elCount);
text('speed pills: ' + (html.match(/class="speed-pill/g) || []).length);
text('scrubber attrs ok: ' + /min="0" max="8\.000" step="0\.001" value="0"/.test(html));
text('DURATION decl: ' + /const DURATION = 8\.000;/.test(src));
return 'checks done';

