217	(function () {
218	'use strict';
219	
220	/* ---------------- deterministic utilities ---------------- */
221	
222	function mulberry32(seed) {
223	  let a = seed >>> 0;
224	  return function () {
225	    a |= 0; a = (a + 0x6D2B79F5) | 0;
226	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
227	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
228	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
229	  };
230	}
231	const clamp = (x, a, b) => x < a ? a : (x > b ? b : x);
232	const lerp = (a, b, u) => a + (b - a) * u;
233	const sstep = (a, b, x) => { const u = clamp((x - a) / (b - a), 0, 1); return u * u * (3 - 2 * u); };
234	
235	const DURATION = 8.000;
236	const T_IMPACT = 1.0, T_RETRACT = 1.6, T_CAV = 2.4, T_EXIT = 3.8, T_BREAK = 5.0;
237	
238	/* world layout: balloon dead-center, bullet flies +X -> -X along y = AXIS_Y */
239	const BAL_R = 0.55, BAL_H = 0.616, BAL_CY = 0.02;
240	const AXIS_Y = 0.02;
241	const ENTRY_X = 0.548, EXIT_X = -0.548;
242	const FLOOR_Y = -1.62;
243	const G_WATER = 0.5, G_DROP = 1.15;
244	const V_IN = (EXIT_X - ENTRY_X) / (T_EXIT - T_IMPACT);   /* inside water */
245	const V_OUT = 0.85;                                       /* after exit  */
246	
247	/* teardrop profile: v = 0 bottom pole .. 1 top pole */
248	function balloonRadius(v) {
249	  const s = Math.sin(Math.PI * Math.pow(clamp(v, 0, 1), 0.82));
250	  return BAL_R * Math.pow(Math.max(s, 0), 0.9) * (1 - 0.22 * sstep(0.55, 1.0, v));
251	}
252	function profileY(v) { return (v - 0.5) * 2 * BAL_H + BAL_CY; }
253	function waterSag(t) { return t > T_RETRACT ? 0.5 * G_WATER * (t - T_RETRACT) * (t - T_RETRACT) : 0; }
254	/* explicit, monotone, phase-exact bullet track */
255	function bulletPos(t) {
256	  if (t <= T_IMPACT) return ENTRY_X + (T_IMPACT - t) * (4.2 - ENTRY_X);
257	  if (t <= T_EXIT) return ENTRY_X + (t - T_IMPACT) * V_IN;
258	  return EXIT_X - (t - T_EXIT) * V_OUT;
259	}
260	
261	/* ---------------- renderer / scene / camera ---------------- */
262	
263	const canvas = document.getElementById('stage');
264	const renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
265	renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
266	renderer.setSize(window.innerWidth, window.innerHeight, false);
267	renderer.outputEncoding = THREE.sRGBEncoding;
268	renderer.setClearColor(0x000000, 0);
269	
270	const scene = new THREE.Scene();
271	const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 60);
272	camera.position.set(0, AXIS_Y, 4.6);
273	camera.lookAt(0, AXIS_Y, 0);
274	
275	/* three-point studio rig: warm key + cool white rim + cyan/magenta tint rim */
276	const keyLight = new THREE.DirectionalLight(0xfff1dd, 1.05);
277	keyLight.position.set(2.6, 3.2, 4.2);
278	scene.add(keyLight);
279	const rimCool = new THREE.DirectionalLight(0xe4f2ff, 1.55);
280	rimCool.position.set(-4.2, 1.6, -3.0);
281	scene.add(rimCool);
282	const rimTint = new THREE.DirectionalLight(0xff5fd0, 0.65);
283	rimTint.position.set(3.6, -1.2, -4.0);
284	scene.add(rimTint);
285	const fillCyan = new THREE.PointLight(0x5fd8ff, 0.55, 20);
286	fillCyan.position.set(-2.2, -0.6, 2.6);
287	scene.add(fillCyan);
288	scene.add(new THREE.AmbientLight(0x2c3244, 0.85));
289	
290	/* ---------------- balloon profile geometry ---------------- */
291	
292	function makeProfilePoints(scaleR, scaleY, n) {
293	  const pts = [];
294	  for (let j = 0; j <= n; j++) {
295	    const v = j / n;
296	    pts.push(new THREE.Vector2(Math.max(balloonRadius(v) * scaleR, 0.0001), (v - 0.5) * 2 * BAL_H * scaleY + BAL_CY));
297	  }
298	  return pts;
299	}
300	
301	/* ---------------- latex membrane (shader tear + retraction) ---------------- */
302	
303	const latexUniforms = {
304	  uT: { value: 0 },
305	  uColor: { value: new THREE.Color('#e61c24').convertSRGBToLinear() },
306	  uKeyDir: { value: new THREE.Vector3(2.6, 3.2, 4.2).normalize() },
307	  uRim1Dir: { value: new THREE.Vector3(-4.2, 1.6, -3.0).normalize() },
308	  uRim2Dir: { value: new THREE.Vector3(3.6, -1.2, -4.0).normalize() }
309	};
310	
311	const latexVert = `
312	uniform float uT;
313	varying vec3 vN;
314	varying vec3 vW;
315	varying vec3 vP0;
316	varying vec2 vUv;
317	float tearFront(vec3 p, vec2 uv) {
318	  float ang = atan(p.z, p.x);
319	  float dAng = abs(atan(sin(ang), cos(ang)));
320	  float prog = smoothstep(1.04, 1.60, uT) * 1.14;
321	  float front = max(dAng / 3.14159265, abs(uv.y - 0.5) / 0.5);
322	  front += (0.05 * sin(ang * 21.0 + uv.y * 55.0) + 0.035 * sin(uv.y * 83.0 + ang * 7.0)) * (0.3 + 0.7 * prog);
323	  return front - prog;
324	}
325	void main() {
326	  vUv = uv;
327	  vP0 = position;
328	  vec3 p = position;
329	  /* elastic indentation around the entry point before the tear */
330	  float dentAmt = smoothstep(1.0, 1.10, uT) * 0.11 * (1.0 - smoothstep(1.18, 1.45, uT));
331	  vec3 ep = vec3(${ENTRY_X.toFixed(4)}, ${AXIS_Y.toFixed(4)}, 0.0);
332	  float d2 = dot(p - ep, p - ep);
333	  p.x -= dentAmt * exp(-d2 / 0.045);
334	  /* curled, fast-retracting torn rim */
335	  float e = tearFront(position, uv);
336	  float c = (uT > 1.04 && e > 0.0 && e < 0.14) ? (1.0 - e / 0.14) : 0.0;
337	  p += normal * (0.055 * c);
338	  p.y += 0.11 * c * sign(uv.y - 0.5);
339	  p.x *= 1.0 - 0.22 * c;
340	  vec4 w = modelMatrix * vec4(p, 1.0);
341	  vW = w.xyz;
342	  vN = normalize(mat3(modelMatrix) * normal);
343	  gl_Position = projectionMatrix * viewMatrix * w;
344	}`;
345	
346	const latexFrag = `
347	uniform float uT;
348	uniform vec3 uColor;
349	uniform vec3 uKeyDir;
350	uniform vec3 uRim1Dir;
351	uniform vec3 uRim2Dir;
352	varying vec3 vN;
353	varying vec3 vW;
354	varying vec3 vP0;
355	varying vec2 vUv;
356	void main() {
357	  float ang = atan(vP0.z, vP0.x);
358	  float dAng = abs(atan(sin(ang), cos(ang)));
359	  float prog = smoothstep(1.04, 1.60, uT) * 1.14;
360	  float front = max(dAng / 3.14159265, abs(vUv.y - 0.5) / 0.5);
361	  front += (0.05 * sin(ang * 21.0 + vUv.y * 55.0) + 0.035 * sin(vUv.y * 83.0 + ang * 7.0)) * (0.3 + 0.7 * prog);
362	  float e = front - prog;
363	  if (uT > 1.04 && e < 0.0) discard;
364	  float c = (uT > 1.04 && e < 0.14) ? (1.0 - e / 0.14) : 0.0;
365	
366	  vec3 N = normalize(vN);
367	  if (!gl_FrontFacing) N = -N;
368	  vec3 V = normalize(cameraPosition - vW);
369	  vec3 H1 = normalize(uKeyDir + V);
370	  vec3 H2 = normalize(uRim1Dir + V);
371	  vec3 H3 = normalize(uRim2Dir + V);
372	
373	  float diff = max(dot(N, uKeyDir), 0.0) * 0.95
374	             + max(dot(N, uRim1Dir), 0.0) * 0.50
375	             + max(dot(N, uRim2Dir), 0.0) * 0.32;
376	  float spec = pow(max(dot(N, H1), 0.0), 140.0) * 1.25
377	             + pow(max(dot(N, H2), 0.0), 90.0) * 1.05
378	             + pow(max(dot(N, H3), 0.0), 70.0) * 0.55;
379	  float fres = pow(1.0 - max(dot(N, V), 0.0), 3.0);
380	  float trans = pow(max(dot(V, -uKeyDir), 0.0), 3.0);
381	
382	  vec3 col = uColor * (0.24 + diff * 0.95);
383	  col += vec3(1.0, 0.97, 0.9) * spec;
384	  col += vec3(0.85, 0.93, 1.0) * fres * 0.50;
385	  col += uColor * fres * 0.85;
386	  col += uColor * trans * 0.65;
387	  col += vec3(1.0, 0.85, 0.8) * c * 0.9;   /* wet glistening tear edge */
388	  float alpha = clamp(0.80 + 0.20 * fres + 0.15 * c, 0.0, 1.0);
389	  gl_FragColor = vec4(col, alpha);
390	  #include <encodings_fragment>
391	}`;
392	
393	const latexGeo = new THREE.LatheGeometry(makeProfilePoints(1, 1, 72), 96);
394	const latexMat = new THREE.ShaderMaterial({
395	  uniforms: latexUniforms,
396	  vertexShader: latexVert,
397	  fragmentShader: latexFrag,
398	  transparent: true,
399	  depthWrite: true,
400	  side: THREE.DoubleSide
401	});
402	const latex = new THREE.Mesh(latexGeo, latexMat);
403	latex.renderOrder = 2;
404	scene.add(latex);
405	
406	/* knot at the neck */
407	const knot = new THREE.Mesh(
408	  new THREE.SphereGeometry(0.045, 16, 12),
409	  new THREE.MeshPhongMaterial({ color: 0xb01218, shininess: 90, specular: 0x884444 })
410	);
411	knot.position.set(0, profileY(1) + 0.02, 0);
412	knot.scale.set(1, 0.75, 1);
413	scene.add(knot);
414	
415	/* tether running off-screen upward, whips after the burst */
416	const tetherGroup = new THREE.Group();
417	tetherGroup.position.set(0, 3.6, 0);
418	const tetherLen = 3.6 - (profileY(1) + 0.04);
419	const tether = new THREE.Mesh(
420	  new THREE.CylinderGeometry(0.0055, 0.0055, tetherLen, 6, 1),
421	  new THREE.MeshBasicMaterial({ color: 0xcdd6e6, transparent: true, opacity: 0.42 })
422	);
423	tether.position.y = -tetherLen / 2;
424	tetherGroup.add(tether);
425	scene.add(tetherGroup);
426	
427	/* ---------------- free-standing water mass ---------------- */
428	
429	const waterGeo = new THREE.LatheGeometry(makeProfilePoints(0.985, 0.985, 56), 64);
430	const waterBase = waterGeo.attributes.position.array.slice();
431	const waterMat = new THREE.MeshPhongMaterial({
432	  color: 0x9fd4ea,
433	  specular: 0xffffff,
434	  shininess: 170,
435	  emissive: 0x0a2436,
436	  transparent: true,
437	  opacity: 0.78,
438	  depthWrite: false,
439	  side: THREE.DoubleSide
440	});
441	const water = new THREE.Mesh(waterGeo, waterMat);
442	water.renderOrder = 1;
443	scene.add(water);
444	
445	function deformWater(t) {
446	  const pos = waterGeo.attributes.position.array;
447	  const n = pos.length / 3;
448	  const sag = waterSag(t);
449	  const dentAmt = sstep(1.0, 1.10, t) * 0.115 * (1 - sstep(1.18, 1.5, t));
450	  const tunnel = 0.165 * sstep(T_CAV, 3.2, t) * (1 - 0.45 * sstep(5.0, 6.2, t));
451	  const coneStretch = 0.13 * sstep(T_EXIT, 4.6, t);
452	  const rtAmp = 0.045 * sstep(4.3, 5.2, t) * (1 + 0.9 * sstep(5.0, 6.4, t));
453	  const shrink = 1 - 0.94 * sstep(5.2, 7.05, t);
454	  const flatten = 1 - 0.06 * sstep(5.0, 7.0, t);
455	  for (let i = 0; i < n; i++) {
456	    const ix = i * 3;
457	    let x = waterBase[ix], y = waterBase[ix + 1], z = waterBase[ix + 2];
458	    if (t >= T_IMPACT) {
459	      const dx = x - ENTRY_X, dy = y - AXIS_Y;
460	      const d2 = dx * dx + dy * dy + z * z;
461	      x -= dentAmt * Math.exp(-d2 / 0.05);
462	      if (tunnel > 0.0001) {
463	        const ry = y - AXIS_Y;
464	        const w = Math.exp(-(ry * ry) / 0.034) * Math.exp(-(z * z) / 0.034) * sstep(0.62, 0.45, Math.abs(x));
465	        const rho = Math.sqrt(ry * ry + z * z);
466	        if (rho > 1e-4) {
467	          y += tunnel * w * (ry / rho);
468	          z += tunnel * w * (z / rho);
469	        } else {
470	          y += tunnel * w;
471	        }
472	      }
473	      x -= coneStretch * sstep(-0.28, -0.55, x);
474	      if (rtAmp > 0.0001) {
475	        const ang = Math.atan2(z, x);
476	        const r = Math.sqrt(x * x + z * z);
477	        const nz = Math.sin(ang * 7 + y * 9.3) * Math.sin(y * 13.1 - ang * 5.2);
478	        const grow = rtAmp * nz * (0.45 + 0.55 * sstep(0.3, -0.5, y));
479	        if (r > 1e-4) { x += grow * (x / r); z += grow * (z / r); }
480	      }
481	      y -= sag * (0.55 + 0.45 * sstep(0.4, -0.6, y));
482	      y *= flatten;
483	      x *= shrink; z *= shrink;
484	      y = AXIS_Y + (y - AXIS_Y) * shrink;
485	    }
486	    pos[ix] = x; pos[ix + 1] = y; pos[ix + 2] = z;
487	  }
488	  waterGeo.attributes.position.needsUpdate = true;
489	  waterGeo.computeVertexNormals();
490	}
