595	  const put = (t0, life, x, y, z, vx, vy, vz, size, drag, grav, alpha, tint, floor) => {
596	    pT0[i] = t0; pLife[i] = life;
597	    pX[i] = x; pY[i] = y; pZ[i] = z;
598	    pVX[i] = vx; pVY[i] = vy; pVZ[i] = vz;
599	    pSize[i] = size; pDrag[i] = drag; pGrav[i] = grav;
600	    pAlpha[i] = alpha; pTint[i] = tint; pFloor[i] = floor;
601	    pSeed[i] = rng();
602	    i++;
603	  };
604	  const gauss = () => (rng() + rng() + rng() - 1.5) * 0.816;
605	
606	  /* 1. backward entry spray — vents from the right puncture */
607	  for (let k = 0; k < N_ENTRY; k++) {
608	    const u = rng();
609	    const t0 = T_IMPACT + 0.55 * u * u;
610	    const sp = 0.7 + 2.7 * Math.pow(rng(), 1.6) + (rng() < 0.06 ? 1.8 : 0);
611	    const dy = gauss() * 0.62, dz = gauss() * 0.62;
612	    const inv = 1 / Math.sqrt(1 + dy * dy + dz * dz);
613	    put(t0, 1.2 + 1.5 * rng(),
614	      ENTRY_X + gauss() * 0.03, AXIS_Y + gauss() * 0.045, gauss() * 0.045,
615	      sp * inv, sp * dy * inv, sp * dz * inv,
616	      0.008 + 0.024 * Math.pow(rng(), 1.7), 0, G_DROP, 0.85, rng() * 0.35, 1);
