623	    const r = balloonRadius(v);
624	    const x = r * Math.cos(ang), z = r * Math.sin(ang), y = profileY(v);
625	    const rl = Math.max(Math.sqrt(x * x + z * z), 1e-4);
626	    const sp = 0.35 + 0.55 * rng();
