222	function mulberry32(seed) {
223	  let a = seed >>> 0;
224	  return function () {
225	    a |= 0; a = (a + 0x6D2B79F5) | 0;
226	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
227	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
228	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
229	  };
230	}
231	const clamp = (x, a, b) => x < a ? a : (x > b ? b : x);
232	const lerp = (a, b, u) => a + (b - a) * u;
233	const sstep = (a, b, x) => { const u = clamp((x - a) / (b - a), 0, 1); return u * u * (3 - 2 * u); };
234	
235	const DURATION = 8.000;
236	const T_IMPACT = 1.0, T_RETRACT = 1.6, T_CAV = 2.4, T_EXIT = 3.8, T_BREAK = 5.0;
237	
238	/* world layout: balloon dead-center, bullet flies +X -> -X along y = AXIS_Y */
239	const BAL_R = 0.55, BAL_H = 0.616, BAL_CY = 0.02;
240	const AXIS_Y = 0.02;
241	const ENTRY_X = 0.548, EXIT_X = -0.548;
242	const FLOOR_Y = -1.62;
243	const G_WATER = 0.5, G_DROP = 1.15;
244	const V_IN = (EXIT_X - ENTRY_X) / (T_EXIT - T_IMPACT);   /* inside water */
245	const V_OUT = 0.85;                                       /* after exit  */
246	
247	/* teardrop profile: v = 0 bottom pole .. 1 top pole */
248	function balloonRadius(v) {
249	  const s = Math.sin(Math.PI * Math.pow(clamp(v, 0, 1), 0.82));
250	  return BAL_R * Math.pow(Math.max(s, 0), 0.9) * (1 - 0.22 * sstep(0.55, 1.0, v));
251	}
252	function profileY(v) { return (v - 0.5) * 2 * BAL_H + BAL_CY; }
