231	const clamp = (x, a, b) => x < a ? a : (x > b ? b : x);
232	const lerp = (a, b, u) => a + (b - a) * u;
233	const sstep = (a, b, x) => { const u = clamp((x - a) / (b - a), 0, 1); return u * u * (3 - 2 * u); };
