496	  new THREE.MeshBasicMaterial({
497	    color: 0xbfeaff, transparent: true, opacity: 0,
498	    blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide
499	  })
500	);
501	vaporCore.rotation.z = Math.PI / 2;
502	vaporCore.position.set(0, AXIS_Y, 0);
