507	
508	const bulletProfile = [
509	  new THREE.Vector2(0.0001, 0), new THREE.Vector2(0.052, 0),
510	  new THREE.Vector2(0.052, 0.095), new THREE.Vector2(0.046, 0.102),
511	  new THREE.Vector2(0.046, 0.124), new THREE.Vector2(0.052, 0.131),
