import socket, json, sys, time, base64

class M:
    def __init__(self):
        self.s = socket.create_connection(('127.0.0.1', 2828), timeout=30)
        self.buf = b''
        self._read_msg()  # greeting
        self.mid = 0
        self.cmd('WebDriver:NewSession', {'capabilities': {}})
    def _read_exact(self, n):
        while len(self.buf) < n:
            d = self.s.recv(65536)
            if not d: raise EOFError('marionette closed')
            self.buf += d
        out, self.buf = self.buf[:n], self.buf[n:]
        return out
    def _read_msg(self):
        head = b''
        while b':' not in head:
            head += self._read_exact(1)
        ln = int(head.split(b':')[0])
        body = self._read_exact(ln)
        return json.loads(body)
    def cmd(self, name, params=None, timeout=60):
        self.mid += 1
        msg = json.dumps([0, self.mid, name, params or {}]).encode()
        self.s.sendall(str(len(msg)).encode() + b':' + msg)
        t0 = time.time()
        while True:
            m = self._read_msg()
            if isinstance(m, list) and m[0] == 1 and m[1] == self.mid:
