762	function updateParticles(t) {
763	  for (let i = 0; i < N; i++) {
764	    const age = t - pT0[i];
765	    const i3 = i * 3;
766	    partTint[i] = pTint[i];
767	    if (age < 0 || age > pLife[i]) {
768	      partAlpha[i] = 0; partSize[i] = 0;
769	      partPos[i3] = 0; partPos[i3 + 1] = -10; partPos[i3 + 2] = 0;
770	      continue;
771	    }
772	    const life = pLife[i];
773	    let x, y, z, sizeMul = 1, extraFade = 1;
774	    const k = pDrag[i], g = pGrav[i];
775	    if (k > 0) {
776	      const ek = (1 - Math.exp(-k * age)) / k;
777	      x = pX[i] + pVX[i] * ek;
778	      z = pZ[i] + pVZ[i] * ek;
779	      y = pY[i] + (pVY[i] + g / k) * ek - (g / k) * age;
780	    } else {
781	      x = pX[i] + pVX[i] * age;
782	      z = pZ[i] + pVZ[i] * age;
783	      y = pY[i] + pVY[i] * age - 0.5 * g * age * age;
784	      if (pFloor[i] === 1 && y < FLOOR_Y && g > 0) {
785	        /* analytic first impact, rebound, then settle & slide */
786	        const vy0 = pVY[i], y0 = pY[i];
787	        const disc = vy0 * vy0 + 2 * g * (y0 - FLOOR_Y);
788	        const a1 = (vy0 + Math.sqrt(Math.max(disc, 0))) / g;
789	        const b = age - a1;
790	        const x1 = pX[i] + pVX[i] * a1, z1 = pZ[i] + pVZ[i] * a1;
791	        const vy1 = (g * a1 - vy0) * 0.30;
792	        const vx1 = pVX[i] * 0.58, vz1 = pVZ[i] * 0.58;
793	        const a2 = 2 * vy1 / g;
794	        if (b <= a2) {
795	          x = x1 + vx1 * b; z = z1 + vz1 * b;
796	          y = FLOOR_Y + vy1 * b - 0.5 * g * b * b;
797	        } else {
798	          const c = b - a2;
799	          const slide = (1 - Math.exp(-2.5 * c)) / 2.5;
800	          x = x1 + vx1 * a2 + vx1 * slide;
801	          z = z1 + vz1 * a2 + vz1 * slide;
802	          y = FLOOR_Y;
803	          sizeMul = 1 + 0.5 * Math.min(c, 0.4);
804	          extraFade = Math.exp(-0.5 * c);
805	        }
806	      }
807	    }
808	    const fadeIn = sstep(0, 0.035, age);
809	    const fadeOut = 1 - sstep(life - 0.4, life, age);
810	    const twinkle = 0.85 + 0.15 * Math.sin(pSeed[i] * 40 + t * (6 + pSeed[i] * 5));
