993	function frame(now) {
994	  requestAnimationFrame(frame);
995	  if (lastNow === null) lastNow = now;
996	  let dt = (now - lastNow) / 1000;
997	  lastNow = now;
998	  if (dt < 0) dt = 0;
999	  if (dt > 0.1) dt = 0.1;
1000	
1001	  if (state === 'INIT') {
