1007	  }
1008	
1009	  if (state === 'COUNTDOWN') {
1010	    const elapsed = (now - countdownStart) / 1000;
1011	    if (elapsed >= 3.0) {
1012	      hideCountdown();
1013	      state = 'PLAYING';
