779	      y = pY[i] + (pVY[i] + g / k) * ek - (g / k) * age;
780	    } else {
781	      x = pX[i] + pVX[i] * age;
782	      z = pZ[i] + pVZ[i] * age;
783	      y = pY[i] + pVY[i] * age - 0.5 * g * age * age;
784	      if (pFloor[i] === 1 && y < FLOOR_Y && g > 0) {
785	        /* analytic first impact, rebound, then settle & slide */
786	        const vy0 = pVY[i], y0 = pY[i];
787	        const disc = vy0 * vy0 + 2 * g * (y0 - FLOOR_Y);
788	        const a1 = (vy0 + Math.sqrt(Math.max(disc, 0))) / g;
789	        const b = age - a1;
790	        const x1 = pX[i] + pVX[i] * a1, z1 = pZ[i] + pVZ[i] * a1;
791	        const vy1 = (g * a1 - vy0) * 0.30;
792	        const vx1 = pVX[i] * 0.58, vz1 = pVZ[i] * 0.58;
793	        const a2 = 2 * vy1 / g;
794	        if (b <= a2) {
795	          x = x1 + vx1 * b; z = z1 + vz1 * b;
796	          y = FLOOR_Y + vy1 * b - 0.5 * g * b * b;
797	        } else {
798	          const c = b - a2;
799	          const slide = (1 - Math.exp(-2.5 * c)) / 2.5;
800	          x = x1 + vx1 * a2 + vx1 * slide;
801	          z = z1 + vz1 * a2 + vz1 * slide;
802	          y = FLOOR_Y;
803	          sizeMul = 1 + 0.5 * Math.min(c, 0.4);
804	          extraFade = Math.exp(-0.5 * c);
805	        }
806	      }
807	    }
808	    const fadeIn = sstep(0, 0.035, age);
809	    const fadeOut = 1 - sstep(life - 0.4, life, age);
810	    const twinkle = 0.85 + 0.15 * Math.sin(pSeed[i] * 40 + t * (6 + pSeed[i] * 5));
811	    partPos[i3] = x; partPos[i3 + 1] = y; partPos[i3 + 2] = z;
812	    partSize[i] = pSize[i] * sizeMul;
813	    partAlpha[i] = pAlpha[i] * fadeIn * fadeOut * twinkle * extraFade;
814	  }
815	  partGeo.attributes.position.needsUpdate = true;
816	  partGeo.attributes.aSize.needsUpdate = true;
817	  partGeo.attributes.aAlpha.needsUpdate = true;
818	  partGeo.attributes.aTint.needsUpdate = true;
819	}
820	
821	/* ---------------- pure deterministic scene evaluation ---------------- */
822	
823	function renderAt(t) {
824	  t = clamp(t, 0, DURATION);
825	
826	  /* latex */
827	  latexUniforms.uT.value = t;
828	  latex.visible = t < 1.72;
829	  const sway = 0.012 * Math.sin(t * 1.7 + 0.5) * (1 - sstep(0.9, 1.05, t));
830	  latex.rotation.z = sway;
831	  knot.visible = t < 1.62;
832	  const knotK = 1 - sstep(1.3, 1.6, t);
833	  knot.scale.set(knotK, 0.75 * knotK, knotK);
834	
835	  /* tether whip after the burst */
836	  if (t > 1.5) {
837	    const dtw = t - 1.5;
838	    tetherGroup.rotation.z = 0.055 * Math.sin(dtw * 17) * Math.exp(-dtw * 2.1);
839	    tetherGroup.rotation.x = 0.03 * Math.sin(dtw * 13 + 1.2) * Math.exp(-dtw * 2.4);
840	  } else {
841	    tetherGroup.rotation.z = 0;
842	    tetherGroup.rotation.x = 0;
843	  }
844	
845	  /* water mass */
846	  water.visible = t < 7.1;
847	  if (water.visible) {
848	    deformWater(t);
849	    water.rotation.z = sway;
850	    waterMat.opacity = 0.78 * (1 - sstep(5.4, 7.0, t)) + 0.04 * sstep(T_RETRACT, T_CAV, t);
851	  }
852	
853	  /* vapor tunnel core */
854	  const coreEnv = sstep(T_CAV, 3.1, t) * (1 - sstep(4.4, 5.3, t));
855	  vaporCore.visible = coreEnv > 0.002;
856	  if (vaporCore.visible) {
857	    const grow = sstep(T_CAV, T_EXIT, t);
858	    vaporCore.scale.set(1, 0.55 + 0.75 * grow, 1);
859	    vaporCore.position.x = lerp(0.18, -0.06, grow);
860	    vaporCore.material.opacity = 0.30 * coreEnv * (0.8 + 0.2 * Math.sin(t * 26));
861	  }
862	
863	  /* bullet */
864	  const bx = bulletPos(t);
865	  bulletGroup.visible = bx > -5.2 && t < 7.5;
866	  bulletGroup.position.set(bx, AXIS_Y, 0);
867	  bulletMesh.rotation.y = t * 55;
868	  if (t < T_IMPACT) {
869	    streak.visible = true;
870	    streak.position.set(bx + 0.62, AXIS_Y, -0.01);
871	    streak.material.opacity = 0.16 * sstep(0.05, 0.4, t);
872	  } else {
873	    streak.visible = false;
874	  }
875	
876	  /* shock rings */
877	  const re = (t - 1.02) / 0.5;
878	  ringEntry.visible = re > 0 && re < 1;
879	  if (ringEntry.visible) {
880	    const s = 0.06 + 0.85 * re;
881	    ringEntry.scale.set(s, s, 1);
882	    ringEntry.material.opacity = 0.45 * (1 - re);
883	  }
884	  const rx = (t - T_EXIT) / 0.55;
885	  ringExit.visible = rx > 0 && rx < 1;
886	  if (ringExit.visible) {
887	    const s = 0.06 + 1.0 * rx;
888	    ringExit.scale.set(s, s, 1);
889	    ringExit.material.opacity = 0.5 * (1 - rx);
890	  }
891	
892	  updateParticles(t);
893	  renderer.render(scene, camera);
894	}
