896	/* ---------------- resize ---------------- */
897	
898	function onResize() {
899	  const w = window.innerWidth, h = window.innerHeight;
900	  camera.aspect = w / h;
901	  camera.updateProjectionMatrix();
902	  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
903	  renderer.setSize(w, h, false);
904	  partUniforms.uScale.value = (h * Math.min(window.devicePixelRatio || 1, 2)) / (2 * Math.tan(THREE.MathUtils.degToRad(17.5)));
905	  renderAt(simTime);
906	}
907	window.addEventListener('resize', onResize);
908	
909	/* ---------------- playback state machine ---------------- */
910	
911	const cd = document.getElementById('countdown');
912	const btnToggle = document.getElementById('btn-toggle');
913	const btnRefire = document.getElementById('btn-refire');
914	const iconPlay = document.getElementById('icon-play');
915	const iconPause = document.getElementById('icon-pause');
916	const scrubber = document.getElementById('scrubber');
917	const pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));
918	
919	let state = 'INIT';            /* INIT -> COUNTDOWN -> PLAYING <-> PAUSED -> ENDED; REFIRE_HOLD */
920	let simTime = 0;
921	let playbackSpeed = 1.0;
922	let countdownStart = 0, holdStart = 0;
923	let lastNow = null;
924	
925	function hideCountdown() { cd.style.display = 'none'; cd.textContent = ''; }
926	function showCountdown(txt) { cd.style.display = 'block'; cd.textContent = txt; }
927	function setPlayingUI() {
928	  iconPause.style.display = '';
929	  iconPlay.style.display = 'none';
930	  btnToggle.setAttribute('aria-label', 'Pause');
931	}
932	function setPausedUI() {
933	  iconPause.style.display = 'none';
934	  iconPlay.style.display = '';
935	  btnToggle.setAttribute('aria-label', 'Play');
936	}
937	function syncScrubber() { scrubber.value = simTime.toFixed(3); }
938	
939	btnToggle.addEventListener('click', function () {
940	  if (state === 'PLAYING') {
941	    state = 'PAUSED';
942	    setPausedUI();
943	  } else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') {
944	    hideCountdown();
945	    simTime = 0;
946	    syncScrubber();
947	    state = 'PAUSED';
948	    setPausedUI();
949	    renderAt(simTime);
950	  } else if (state === 'PAUSED' || state === 'INIT') {
951	    hideCountdown();
952	    state = 'PLAYING';
953	    setPlayingUI();
954	  } else if (state === 'ENDED') {
955	    hideCountdown();
956	    simTime = 0;
957	    syncScrubber();
958	    state = 'PLAYING';
959	    setPlayingUI();
960	    renderAt(simTime);
961	  }
962	});
963	
964	btnRefire.addEventListener('click', function () {
965	  hideCountdown();
966	  simTime = 0;
967	  scrubber.value = '0';
968	  state = 'REFIRE_HOLD';
969	  holdStart = performance.now();
970	  setPlayingUI();
971	  renderAt(0);
972	});
973	
974	scrubber.addEventListener('input', function () {
975	  if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD' || state === 'INIT') hideCountdown();
976	  simTime = clamp(parseFloat(scrubber.value) || 0, 0, DURATION);
977	  state = 'PAUSED';
978	  setPausedUI();
979	  renderAt(simTime);
980	});
981	
982	pills.forEach(function (pill) {
983	  pill.addEventListener('click', function () {
984	    playbackSpeed = parseFloat(pill.getAttribute('data-speed'));
985	    pills.forEach(function (p) {
986	      const active = p === pill;
987	      p.classList.toggle('is-active', active);
988	      p.setAttribute('aria-checked', active ? 'true' : 'false');
989	    });
990	  });
991	});
992	
993	function frame(now) {
994	  requestAnimationFrame(frame);
995	  if (lastNow === null) lastNow = now;
996	  let dt = (now - lastNow) / 1000;
997	  lastNow = now;
998	  if (dt < 0) dt = 0;
999	  if (dt > 0.1) dt = 0.1;
1000	
1001	  if (state === 'INIT') {
1002	    /* initial resting scene already rendered; begin the 3 s wall-clock countdown */
1003	    state = 'COUNTDOWN';
1004	    countdownStart = now;
1005	    showCountdown('3');
1006	    return;
1007	  }
1008	
1009	  if (state === 'COUNTDOWN') {
1010	    const elapsed = (now - countdownStart) / 1000;
1011	    if (elapsed >= 3.0) {
1012	      hideCountdown();
1013	      state = 'PLAYING';
1014	      setPlayingUI();
1015	      simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
1016	      syncScrubber();
1017	    } else {
1018	      showCountdown(elapsed < 1 ? '3' : (elapsed < 2 ? '2' : '1'));
1019	      simTime = 0;
1020	    }
1021	  } else if (state === 'REFIRE_HOLD') {
1022	    const elapsed = (now - holdStart) / 1000;
1023	    if (elapsed >= 1.0) {
1024	      state = 'PLAYING';
1025	      simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
1026	      syncScrubber();
1027	    }
1028	  } else if (state === 'PLAYING') {
1029	    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
1030	    syncScrubber();
1031	    if (simTime >= DURATION) {
1032	      simTime = DURATION;
1033	      syncScrubber();
1034	      state = 'ENDED';
1035	      setPausedUI();
1036	    }
1037	  }
1038	
1039	  renderAt(simTime);
1040	}
1041	
1042	/* initial resting frame, then start the loop */
1043	partUniforms.uScale.value = (window.innerHeight * Math.min(window.devicePixelRatio || 1, 2)) / (2 * Math.tan(THREE.MathUtils.degToRad(17.5)));
1044	renderAt(0);
1045	requestAnimationFrame(frame);
1046	
1047	})();
