839	    tetherGroup.rotation.x = 0.03 * Math.sin(dtw * 13 + 1.2) * Math.exp(-dtw * 2.4);
840	  } else {
841	    tetherGroup.rotation.z = 0;
842	    tetherGroup.rotation.x = 0;
843	  }
844	
845	  /* water mass */
846	  water.visible = t < 7.1;
847	  if (water.visible) {
848	    deformWater(t);
849	    water.rotation.z = sway;
850	    waterMat.opacity = 0.78 * (1 - sstep(5.4, 7.0, t)) + 0.04 * sstep(T_RETRACT, T_CAV, t);
851	  }
852	
853	  /* vapor tunnel core */
854	  const coreEnv = sstep(T_CAV, 3.1, t) * (1 - sstep(4.4, 5.3, t));
855	  vaporCore.visible = coreEnv > 0.002;
856	  if (vaporCore.visible) {
857	    const grow = sstep(T_CAV, T_EXIT, t);
858	    vaporCore.scale.set(1, 0.55 + 0.75 * grow, 1);
859	    vaporCore.position.x = lerp(0.18, -0.06, grow);
860	    vaporCore.material.opacity = 0.30 * coreEnv * (0.8 + 0.2 * Math.sin(t * 26));
861	  }
862	
863	  /* bullet */
864	  const bx = bulletPos(t);
865	  bulletGroup.visible = bx > -5.2 && t < 7.5;
866	  bulletGroup.position.set(bx, AXIS_Y, 0);
867	  bulletMesh.rotation.y = t * 55;
868	  if (t < T_IMPACT) {
869	    streak.visible = true;
870	    streak.position.set(bx + 0.62, AXIS_Y, -0.01);
871	    streak.material.opacity = 0.16 * sstep(0.05, 0.4, t);
872	  } else {
873	    streak.visible = false;
874	  }
875	
876	  /* shock rings */
877	  const re = (t - 1.02) / 0.5;
878	  ringEntry.visible = re > 0 && re < 1;
879	  if (ringEntry.visible) {
880	    const s = 0.06 + 0.85 * re;
881	    ringEntry.scale.set(s, s, 1);
882	    ringEntry.material.opacity = 0.3 * (1 - re);
883	  }
884	  const rx = (t - T_EXIT) / 0.55;
885	  ringExit.visible = rx > 0 && rx < 1;
886	  if (ringExit.visible) {
887	    const s = 0.06 + 1.0 * rx;
888	    ringExit.scale.set(s, s, 1);
889	    ringExit.material.opacity = 0.35 * (1 - rx);
890	  }
891	
892	  updateParticles(t);
893	  renderer.render(scene, camera);
894	}
