python3 -c "
import zlib, struct
def load(path):
    b=open(path,'rb').read(); off=8; idat=[]
    while off<len(b):
        ln=struct.unpack('>I',b[off:off+4])[0]; ty=b[off+4:off+8]; data=b[off+8:off+8+ln]
        if ty==b'IHDR': w,h,bd,ct=struct.unpack('>IIBB',data[:10])
        elif ty==b'IDAT': idat.append(data)
        off+=12+ln
    raw=zlib.decompress(b''.join(idat)); ch=4 if ct==6 else 3; stride=w*ch
    out=bytearray(w*h*ch); prev=bytearray(stride); rp=0
    for y in range(h):
        f=raw[rp]; rp+=1; line=bytearray(raw[rp:rp+stride]); rp+=stride
        if f==1:
            for x in range(ch,stride): line[x]=(line[x]+line[x-ch])&255
        elif f==2:
            for x in range(stride): line[x]=(line[x]+prev[x])&255
        elif f==3:
            for x in range(stride):
                a=line[x-ch] if x>=ch else 0; line[x]=(line[x]+((a+prev[x])>>1))&255
        elif f==4:
            for x in range(stride):
                a=line[x-ch] if x>=ch else 0; c=prev[x-ch] if x>=ch else 0; bb=prev[x]
                p=a+bb-c; pa,pb,pc=abs(p-a),abs(p-bb),abs(p-c)
                pr=a if (pa<=pb and pa<=pc) else (bb if pb<=pc else c)
                line[x]=(line[x]+pr)&255
        out[y*stride:(y+1)*stride]=line; prev=line
    return w,h,ch,out
w,h,ch,px=load('impact_m.png')
warm={}
for y in range(0,h):
    for x in range(0,w):
        i=(y*w+x)*ch; r,g,b=px[i],px[i+1],px[i+2]
        if r>70 and r-b>25 and r-g>8:
            key=(x//40,y//40)
            warm.setdefault(key,[0,0,0,0])
            warm[key][0]+=1; warm[key][1]+=r; warm[key][2]+=g; warm[key][3]+=b
top=sorted(warm.items(), key=lambda kv:-kv[1][0])[:12]
for (bx,by),(n,r,g,b) in top:
    print('block px',bx*40,by*40,'count',n,'avg',r//n,g//n,b//n)
"

