215	<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
216	<script>
217	(function () {
218	'use strict';
219	
220	/* ---------------- deterministic utilities ---------------- */
221	
222	function mulberry32(seed) {
223	  let a = seed >>> 0;
224	  return function () {
225	    a |= 0; a = (a + 0x6D2B79F5) | 0;
226	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
227	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
228	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
229	  };
230	}
231	const clamp = (x, a, b) => x < a ? a : (x > b ? b : x);
232	const lerp = (a, b, u) => a + (b - a) * u;
233	const sstep = (a, b, x) => { const u = clamp((x - a) / (b - a), 0, 1); return u * u * (3 - 2 * u); };
234	
235	const DURATION = 8.000;
236	const T_IMPACT = 1.0, T_RETRACT = 1.6, T_CAV = 2.4, T_EXIT = 3.8, T_BREAK = 5.0;
237	
238	/* world layout: balloon dead-center, bullet flies +X -> -X along y = AXIS_Y */
239	const BAL_R = 0.55, BAL_H = 0.616, BAL_CY = 0.02;
240	const AXIS_Y = 0.02;
241	const ENTRY_X = 0.548, EXIT_X = -0.548;
242	const FLOOR_Y = -1.62;
243	const G_WATER = 0.5, G_DROP = 1.15;
244	const V_IN = (EXIT_X - ENTRY_X) / (T_EXIT - T_IMPACT);   /* inside water */
245	const V_OUT = 0.85;                                       /* after exit  */
246	
247	/* teardrop profile: v = 0 bottom pole .. 1 top pole */
248	function balloonRadius(v) {
249	  const s = Math.sin(Math.PI * Math.pow(clamp(v, 0, 1), 0.82));
250	  return BAL_R * Math.pow(Math.max(s, 0), 0.9) * (1 - 0.22 * sstep(0.55, 1.0, v));
251	}
252	function profileY(v) { return (v - 0.5) * 2 * BAL_H + BAL_CY; }
253	function waterSag(t) { return t > T_RETRACT ? 0.5 * G_WATER * (t - T_RETRACT) * (t - T_RETRACT) : 0; }
254	/* explicit, monotone, phase-exact bullet track */
255	function bulletPos(t) {
256	  if (t <= T_IMPACT) return ENTRY_X + (T_IMPACT - t) * (4.2 - ENTRY_X);
257	  if (t <= T_EXIT) return ENTRY_X + (t - T_IMPACT) * V_IN;
258	  return EXIT_X - (t - T_EXIT) * V_OUT;
259	}
260	
261	/* ---------------- renderer / scene / camera ---------------- */
262	
263	const canvas = document.getElementById('stage');
264	const renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
265	renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
266	renderer.setSize(window.innerWidth, window.innerHeight, false);
267	renderer.outputEncoding = THREE.sRGBEncoding;
268	renderer.setClearColor(0x000000, 0);
269	
270	const scene = new THREE.Scene();
271	const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 60);
272	camera.position.set(0, AXIS_Y, 4.6);
273	camera.lookAt(0, AXIS_Y, 0);
274	
275	/* three-point studio rig: warm key + cool white rim + cyan/magenta tint rim */
276	const keyLight = new THREE.DirectionalLight(0xfff1dd, 0.85);
277	keyLight.position.set(2.6, 3.2, 4.2);
278	scene.add(keyLight);
279	const rimCool = new THREE.DirectionalLight(0xe4f2ff, 1.1);
280	rimCool.position.set(-4.2, 1.6, -3.0);
281	scene.add(rimCool);
282	const rimTint = new THREE.DirectionalLight(0xff5fd0, 0.5);
283	rimTint.position.set(3.6, -1.2, -4.0);
284	scene.add(rimTint);
285	const fillCyan = new THREE.PointLight(0x5fd8ff, 0.4, 20);
286	fillCyan.position.set(-2.2, -0.6, 2.6);
287	scene.add(fillCyan);
288	const fillFront = new THREE.DirectionalLight(0xffe6c8, 0.32);
289	fillFront.position.set(0.6, 0.5, 5.0);
290	scene.add(fillFront);
291	scene.add(new THREE.AmbientLight(0x2c3244, 0.6));
292	
293	/* ---------------- balloon profile geometry ---------------- */
294	
295	function makeProfilePoints(scaleR, scaleY, n) {
296	  const pts = [];
297	  for (let j = 0; j <= n; j++) {
298	    const v = j / n;
299	    pts.push(new THREE.Vector2(Math.max(balloonRadius(v) * scaleR, 0.0001), (v - 0.5) * 2 * BAL_H * scaleY + BAL_CY));
300	  }
301	  return pts;
302	}
303	
304	/* ---------------- latex membrane (shader tear + retraction) ---------------- */
305	
306	const latexUniforms = {
307	  uT: { value: 0 },
308	  uColor: { value: new THREE.Color('#e61c24').convertSRGBToLinear() },
309	  uKeyDir: { value: new THREE.Vector3(2.6, 3.2, 4.2).normalize() },
310	  uRim1Dir: { value: new THREE.Vector3(-4.2, 1.6, -3.0).normalize() },
311	  uRim2Dir: { value: new THREE.Vector3(3.6, -1.2, -4.0).normalize() }
312	};
313	
314	const latexVert = `
315	uniform float uT;
316	varying vec3 vN;
317	varying vec3 vW;
318	varying vec3 vP0;
319	varying vec2 vUv;
320	float tearFront(vec3 p, vec2 uv) {
321	  float ang = atan(p.z, p.x);
322	  float dAng = abs(atan(sin(ang), cos(ang)));
323	  float prog = smoothstep(1.04, 1.60, uT) * 1.14;
324	  float front = max(dAng / 3.14159265, abs(uv.y - 0.5) / 0.5);
325	  front += (0.05 * sin(ang * 21.0 + uv.y * 55.0) + 0.035 * sin(uv.y * 83.0 + ang * 7.0)) * (0.3 + 0.7 * prog);
326	  return front - prog;
327	}
328	void main() {
329	  vUv = uv;
330	  vP0 = position;
331	  vec3 p = position;
332	  /* elastic indentation around the entry point before the tear */
333	  float dentAmt = smoothstep(1.0, 1.10, uT) * 0.11 * (1.0 - smoothstep(1.18, 1.45, uT));
334	  vec3 ep = vec3(${ENTRY_X.toFixed(4)}, ${AXIS_Y.toFixed(4)}, 0.0);
335	  float d2 = dot(p - ep, p - ep);
336	  p.x -= dentAmt * exp(-d2 / 0.045);
337	  /* curled, fast-retracting torn rim */
338	  float e = tearFront(position, uv);
339	  float c = (uT > 1.04 && e > 0.0 && e < 0.14) ? (1.0 - e / 0.14) : 0.0;
340	  p += normal * (0.055 * c);
341	  p.y += 0.11 * c * sign(uv.y - 0.5);
342	  p.x *= 1.0 - 0.22 * c;
343	  vec4 w = modelMatrix * vec4(p, 1.0);
344	  vW = w.xyz;
345	  vN = normalize(mat3(modelMatrix) * normal);
346	  gl_Position = projectionMatrix * viewMatrix * w;
347	}`;
348	
349	const latexFrag = `
350	uniform float uT;
351	uniform vec3 uColor;
352	uniform vec3 uKeyDir;
353	uniform vec3 uRim1Dir;
354	uniform vec3 uRim2Dir;
355	varying vec3 vN;
356	varying vec3 vW;
357	varying vec3 vP0;
358	varying vec2 vUv;
359	void main() {
360	  float ang = atan(vP0.z, vP0.x);
361	  float dAng = abs(atan(sin(ang), cos(ang)));
362	  float prog = smoothstep(1.04, 1.60, uT) * 1.14;
363	  float front = max(dAng / 3.14159265, abs(vUv.y - 0.5) / 0.5);
364	  front += (0.05 * sin(ang * 21.0 + vUv.y * 55.0) + 0.035 * sin(vUv.y * 83.0 + ang * 7.0)) * (0.3 + 0.7 * prog);
365	  float e = front - prog;
366	  if (uT > 1.04 && e < 0.0) discard;
367	  float c = (uT > 1.04 && e < 0.14) ? (1.0 - e / 0.14) : 0.0;
368	
369	  vec3 N = normalize(vN);
370	  if (!gl_FrontFacing) N = -N;
371	  vec3 V = normalize(cameraPosition - vW);
372	  vec3 H1 = normalize(uKeyDir + V);
373	  vec3 H2 = normalize(uRim1Dir + V);
374	  vec3 H3 = normalize(uRim2Dir + V);
375	
376	  float diff = max(dot(N, uKeyDir), 0.0) * 0.95
377	             + max(dot(N, uRim1Dir), 0.0) * 0.50
378	             + max(dot(N, uRim2Dir), 0.0) * 0.32;
379	  float spec = pow(max(dot(N, H1), 0.0), 140.0) * 1.25
380	             + pow(max(dot(N, H2), 0.0), 90.0) * 1.05
381	             + pow(max(dot(N, H3), 0.0), 70.0) * 0.55;
382	  float fres = pow(1.0 - max(dot(N, V), 0.0), 3.0);
383	  float trans = pow(max(dot(V, -uKeyDir), 0.0), 3.0);
384	
385	  vec3 col = uColor * (0.24 + diff * 0.95);
386	  col += vec3(1.0, 0.97, 0.9) * spec;
387	  col += vec3(0.85, 0.93, 1.0) * fres * 0.50;
388	  col += uColor * fres * 0.85;
389	  col += uColor * trans * 0.65;
390	  col += vec3(1.0, 0.85, 0.8) * c * 0.9;   /* wet glistening tear edge */
391	  float alpha = clamp(0.80 + 0.20 * fres + 0.15 * c, 0.0, 1.0);
392	  gl_FragColor = vec4(col, alpha);
393	  #include <encodings_fragment>
394	}`;
395	
396	const latexGeo = new THREE.LatheGeometry(makeProfilePoints(1, 1, 72), 96);
397	const latexMat = new THREE.ShaderMaterial({
398	  uniforms: latexUniforms,
399	  vertexShader: latexVert,
400	  fragmentShader: latexFrag,
401	  transparent: true,
402	  depthWrite: true,
403	  side: THREE.DoubleSide
404	});
405	const latex = new THREE.Mesh(latexGeo, latexMat);
406	latex.renderOrder = 2;
407	scene.add(latex);
408	
409	/* knot at the neck */
410	const knot = new THREE.Mesh(
411	  new THREE.SphereGeometry(0.045, 16, 12),
412	  new THREE.MeshPhongMaterial({ color: 0xb01218, shininess: 90, specular: 0x884444 })
413	);
414	knot.position.set(0, profileY(1) + 0.02, 0);
415	knot.scale.set(1, 0.75, 1);
416	scene.add(knot);
417	
418	/* tether running off-screen upward, whips after the burst */
419	const tetherGroup = new THREE.Group();
420	tetherGroup.position.set(0, 3.6, 0);
421	const tetherLen = 3.6 - (profileY(1) + 0.04);
422	const tether = new THREE.Mesh(
423	  new THREE.CylinderGeometry(0.0055, 0.0055, tetherLen, 6, 1),
424	  new THREE.MeshBasicMaterial({ color: 0xcdd6e6, transparent: true, opacity: 0.42 })
425	);
426	tether.position.y = -tetherLen / 2;
427	tetherGroup.add(tether);
428	scene.add(tetherGroup);
429	
430	/* ---------------- free-standing water mass ---------------- */
431	
432	const waterGeo = new THREE.LatheGeometry(makeProfilePoints(0.985, 0.985, 56), 64);
433	const waterBase = waterGeo.attributes.position.array.slice();
434	const waterMat = new THREE.MeshPhongMaterial({
435	  color: 0x9fd4ea,
436	  specular: 0xffffff,
437	  shininess: 170,
438	  emissive: 0x0a2436,
439	  transparent: true,
440	  opacity: 0.78,
441	  depthWrite: false,
442	  side: THREE.DoubleSide
443	});
444	const water = new THREE.Mesh(waterGeo, waterMat);
445	water.renderOrder = 1;
446	scene.add(water);
447	
448	function deformWater(t) {
449	  const pos = waterGeo.attributes.position.array;
450	  const n = pos.length / 3;
451	  const sag = waterSag(t);
452	  const dentAmt = sstep(1.0, 1.10, t) * 0.115 * (1 - sstep(1.18, 1.5, t));
453	  const tunnel = 0.165 * sstep(T_CAV, 3.2, t) * (1 - 0.45 * sstep(5.0, 6.2, t));
454	  const coneStretch = 0.13 * sstep(T_EXIT, 4.6, t);
455	  const rtAmp = 0.045 * sstep(4.3, 5.2, t) * (1 + 0.9 * sstep(5.0, 6.4, t));
456	  const shrink = 1 - 0.94 * sstep(5.2, 7.05, t);
457	  const flatten = 1 - 0.06 * sstep(5.0, 7.0, t);
458	  for (let i = 0; i < n; i++) {
459	    const ix = i * 3;
460	    let x = waterBase[ix], y = waterBase[ix + 1], z = waterBase[ix + 2];
461	    if (t >= T_IMPACT) {
462	      const dx = x - ENTRY_X, dy = y - AXIS_Y;
463	      const d2 = dx * dx + dy * dy + z * z;
464	      x -= dentAmt * Math.exp(-d2 / 0.05);
465	      if (tunnel > 0.0001) {
466	        const ry = y - AXIS_Y;
467	        const w = Math.exp(-(ry * ry) / 0.034) * Math.exp(-(z * z) / 0.034) * sstep(0.62, 0.45, Math.abs(x));
468	        const rho = Math.sqrt(ry * ry + z * z);
469	        if (rho > 1e-4) {
470	          y += tunnel * w * (ry / rho);
471	          z += tunnel * w * (z / rho);
472	        } else {
473	          y += tunnel * w;
474	        }
475	      }
476	      x -= coneStretch * sstep(-0.28, -0.55, x);
477	      if (rtAmp > 0.0001) {
478	        const ang = Math.atan2(z, x);
479	        const r = Math.sqrt(x * x + z * z);
480	        const nz = Math.sin(ang * 7 + y * 9.3) * Math.sin(y * 13.1 - ang * 5.2);
481	        const grow = rtAmp * nz * (0.45 + 0.55 * sstep(0.3, -0.5, y));
482	        if (r > 1e-4) { x += grow * (x / r); z += grow * (z / r); }
483	      }
484	      y -= sag * (0.55 + 0.45 * sstep(0.4, -0.6, y));
485	      y *= flatten;
486	      x *= shrink; z *= shrink;
487	      y = AXIS_Y + (y - AXIS_Y) * shrink;
488	    }
489	    pos[ix] = x; pos[ix + 1] = y; pos[ix + 2] = z;
490	  }
491	  waterGeo.attributes.position.needsUpdate = true;
492	  waterGeo.computeVertexNormals();
493	}
494	
495	/* ---------------- cavitation vapor core ---------------- */
496	
497	const vaporCore = new THREE.Mesh(
498	  new THREE.CylinderGeometry(0.075, 0.105, 1.0, 20, 1, true),
499	  new THREE.MeshBasicMaterial({
500	    color: 0xbfeaff, transparent: true, opacity: 0,
501	    blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide
502	  })
503	);
504	vaporCore.rotation.z = Math.PI / 2;
505	vaporCore.position.set(0, AXIS_Y, 0);
506	vaporCore.renderOrder = 3;
507	scene.add(vaporCore);
508	
509	/* ---------------- bullet ---------------- */
510	
