725	  vertexShader: `
726	    attribute float aSize;
727	    attribute float aAlpha;
728	    attribute float aTint;
729	    uniform float uScale;
730	    varying float vAlpha;
731	    varying float vTint;
732	    void main() {
733	      vAlpha = aAlpha;
734	      vTint = aTint;
735	      vec4 mv = modelViewMatrix * vec4(position, 1.0);
736	      gl_PointSize = clamp(aSize * uScale / max(-mv.z, 0.1), 0.0, 160.0);
737	      gl_Position = projectionMatrix * mv;
738	      if (aAlpha <= 0.001) gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
739	    }`,
740	  fragmentShader: `
741	    uniform sampler2D uMap;
742	    varying float vAlpha;
743	    varying float vTint;
744	    void main() {
745	      vec4 tex = texture2D(uMap, gl_PointCoord);
