871	    streak.material.opacity = 0.16 * sstep(0.05, 0.4, t);
872	  } else {
873	    streak.visible = false;
874	  }
875	
876	  /* shock rings */
877	  const re = (t - 1.02) / 0.5;
878	  ringEntry.visible = re > 0 && re < 1;
879	  if (ringEntry.visible) {
880	    const s = 0.06 + 0.85 * re;
881	    ringEntry.scale.set(s, s, 1);
882	    ringEntry.material.opacity = 0.3 * (1 - re);
883	  }
884	  const rx = (t - T_EXIT) / 0.55;
885	  ringExit.visible = rx > 0 && rx < 1;
886	  if (ringExit.visible) {
887	    const s = 0.06 + 1.0 * rx;
888	    ringExit.scale.set(s, s, 1);
889	    ringExit.material.opacity = 0.35 * (1 - rx);
890	  }
891	
892	  updateParticles(t);
893	  renderer.render(scene, camera);
894	}
