909	/* ---------------- playback state machine ---------------- */
910	
911	const cd = document.getElementById('countdown');
912	const btnToggle = document.getElementById('btn-toggle');
913	const btnRefire = document.getElementById('btn-refire');
914	const iconPlay = document.getElementById('icon-play');
915	const iconPause = document.getElementById('icon-pause');
916	const scrubber = document.getElementById('scrubber');
917	const pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));
918	
919	let state = 'INIT';            /* INIT -> COUNTDOWN -> PLAYING <-> PAUSED -> ENDED; REFIRE_HOLD */
920	let simTime = 0;
921	let playbackSpeed = 1.0;
922	let countdownStart = 0, holdStart = 0;
923	let lastNow = null;
924	
925	function hideCountdown() { cd.style.display = 'none'; cd.textContent = ''; }
