998	  if (dt < 0) dt = 0;
999	  if (dt > 0.1) dt = 0.1;
1000	
1001	  if (state === 'INIT') {
1002	    /* initial resting scene already rendered; begin the 3 s wall-clock countdown */
1003	    state = 'COUNTDOWN';
1004	    countdownStart = now;
1005	    showCountdown('3');
1006	    return;
1007	  }
1008	
1009	  if (state === 'COUNTDOWN') {
1010	    const elapsed = (now - countdownStart) / 1000;
1011	    if (elapsed >= 3.0) {
1012	      hideCountdown();
1013	      state = 'PLAYING';
1014	      setPlayingUI();
1015	      simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
1016	      syncScrubber();
1017	    } else {
1018	      showCountdown(elapsed < 1 ? '3' : (elapsed < 2 ? '2' : '1'));
1019	      simTime = 0;
1020	    }
1021	  } else if (state === 'REFIRE_HOLD') {
1022	    const elapsed = (now - holdStart) / 1000;
1023	    if (elapsed >= 1.0) {
1024	      state = 'PLAYING';
1025	      simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
1026	      syncScrubber();
1027	    }
1028	  } else if (state === 'PLAYING') {
1029	    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
1030	    syncScrubber();
1031	    if (simTime >= DURATION) {
1032	      simTime = DURATION;
1033	      syncScrubber();
1034	      state = 'ENDED';
1035	      setPausedUI();
1036	    }
1037	  }
1038	
1039	  renderAt(simTime);
1040	}
