448	function deformWater(t) {
449	  const pos = waterGeo.attributes.position.array;
450	  const n = pos.length / 3;
451	  const sag = waterSag(t);
452	  const dentAmt = sstep(1.0, 1.10, t) * 0.115 * (1 - sstep(1.18, 1.5, t));
453	  const tunnel = 0.165 * sstep(T_CAV, 3.2, t) * (1 - 0.45 * sstep(5.0, 6.2, t));
454	  const coneStretch = 0.13 * sstep(T_EXIT, 4.6, t);
455	  const rtAmp = 0.045 * sstep(4.3, 5.2, t) * (1 + 0.9 * sstep(5.0, 6.4, t));
456	  const shrink = 1 - 0.94 * sstep(5.2, 7.05, t);
457	  const flatten = 1 - 0.06 * sstep(5.0, 7.0, t);
458	  for (let i = 0; i < n; i++) {
459	    const ix = i * 3;
460	    let x = waterBase[ix], y = waterBase[ix + 1], z = waterBase[ix + 2];
461	    if (t >= T_IMPACT) {
462	      const dx = x - ENTRY_X, dy = y - AXIS_Y;
463	      const d2 = dx * dx + dy * dy + z * z;
464	      x -= dentAmt * Math.exp(-d2 / 0.05);
465	      if (tunnel > 0.0001) {
466	        const ry = y - AXIS_Y;
467	        const w = Math.exp(-(ry * ry) / 0.034) * Math.exp(-(z * z) / 0.034) * sstep(0.62, 0.45, Math.abs(x));
468	        const rho = Math.sqrt(ry * ry + z * z);
469	        if (rho > 1e-4) {
470	          y += tunnel * w * (ry / rho);
471	          z += tunnel * w * (z / rho);
472	        } else {
473	          y += tunnel * w;
474	        }
475	      }
476	      x -= coneStretch * sstep(-0.28, -0.55, x);
477	      if (rtAmp > 0.0001) {
478	        const ang = Math.atan2(z, x);
479	        const r = Math.sqrt(x * x + z * z);
480	        const nz = Math.sin(ang * 7 + y * 9.3) * Math.sin(y * 13.1 - ang * 5.2);
481	        const grow = rtAmp * nz * (0.45 + 0.55 * sstep(0.3, -0.5, y));
482	        if (r > 1e-4) { x += grow * (x / r); z += grow * (z / r); }
483	      }
484	      y -= sag * (0.55 + 0.45 * sstep(0.4, -0.6, y));
485	      y *= flatten;
486	      x *= shrink; z *= shrink;
487	      y = AXIS_Y + (y - AXIS_Y) * shrink;
488	    }
489	    pos[ix] = x; pos[ix + 1] = y; pos[ix + 2] = z;
490	  }
491	  waterGeo.attributes.position.needsUpdate = true;
492	  waterGeo.computeVertexNormals();
493	}
