599	    pT0[i] = t0; pLife[i] = life;
600	    pX[i] = x; pY[i] = y; pZ[i] = z;
601	    pVX[i] = vx; pVY[i] = vy; pVZ[i] = vz;
602	    pSize[i] = size; pDrag[i] = drag; pGrav[i] = grav;
603	    pAlpha[i] = alpha; pTint[i] = tint; pFloor[i] = floor;
