778	      z = pZ[i] + pVZ[i] * ek;
779	      y = pY[i] + (pVY[i] + g / k) * ek - (g / k) * age;
780	    } else {
781	      x = pX[i] + pVX[i] * age;
782	      z = pZ[i] + pVZ[i] * age;
783	      y = pY[i] + pVY[i] * age - 0.5 * g * age * age;
784	      if (pFloor[i] === 1 && y < FLOOR_Y && g > 0) {
785	        /* analytic first impact, rebound, then settle & slide */
