271	const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 60);
272	camera.position.set(0, AXIS_Y, 4.6);
273	camera.lookAt(0, AXIS_Y, 0);
274	
275	/* three-point studio rig: warm key + cool white rim + cyan/magenta tint rim */
276	const keyLight = new THREE.DirectionalLight(0xfff1dd, 0.85);
277	keyLight.position.set(2.6, 3.2, 4.2);
278	scene.add(keyLight);
279	const rimCool = new THREE.DirectionalLight(0xe4f2ff, 1.1);
280	rimCool.position.set(-4.2, 1.6, -3.0);
281	scene.add(rimCool);
282	const rimTint = new THREE.DirectionalLight(0xff5fd0, 0.5);
283	rimTint.position.set(3.6, -1.2, -4.0);
284	scene.add(rimTint);
285	const fillCyan = new THREE.PointLight(0x5fd8ff, 0.4, 20);
286	fillCyan.position.set(-2.2, -0.6, 2.6);
287	scene.add(fillCyan);
288	const fillFront = new THREE.DirectionalLight(0xffe6c8, 0.32);
289	fillFront.position.set(0.6, 0.5, 5.0);
290	scene.add(fillFront);
291	scene.add(new THREE.AmbientLight(0x2c3244, 0.6));
292	
293	/* ---------------- balloon profile geometry ---------------- */
294	
295	function makeProfilePoints(scaleR, scaleY, n) {
296	  const pts = [];
297	  for (let j = 0; j <= n; j++) {
298	    const v = j / n;
299	    pts.push(new THREE.Vector2(Math.max(balloonRadius(v) * scaleR, 0.0001), (v - 0.5) * 2 * BAL_H * scaleY + BAL_CY));
300	  }
301	  return pts;
302	}
303	
304	/* ---------------- latex membrane (shader tear + retraction) ---------------- */
305	
306	const latexUniforms = {
307	  uT: { value: 0 },
308	  uColor: { value: new THREE.Color('#e61c24').convertSRGBToLinear() },
309	  uKeyDir: { value: new THREE.Vector3(2.6, 3.2, 4.2).normalize() },
310	  uRim1Dir: { value: new THREE.Vector3(-4.2, 1.6, -3.0).normalize() },
311	  uRim2Dir: { value: new THREE.Vector3(3.6, -1.2, -4.0).normalize() }
312	};
313	
314	const latexVert = `
315	uniform float uT;
316	varying vec3 vN;
317	varying vec3 vW;
318	varying vec3 vP0;
319	varying vec2 vUv;
320	float tearFront(vec3 p, vec2 uv) {
321	  float ang = atan(p.z, p.x);
322	  float dAng = abs(atan(sin(ang), cos(ang)));
323	  float prog = smoothstep(1.04, 1.60, uT) * 1.14;
324	  float front = max(dAng / 3.14159265, abs(uv.y - 0.5) / 0.5);
325	  front += (0.05 * sin(ang * 21.0 + uv.y * 55.0) + 0.035 * sin(uv.y * 83.0 + ang * 7.0)) * (0.3 + 0.7 * prog);
326	  return front - prog;
327	}
328	void main() {
329	  vUv = uv;
330	  vP0 = position;
331	  vec3 p = position;
332	  /* elastic indentation around the entry point before the tear */
333	  float dentAmt = smoothstep(1.0, 1.10, uT) * 0.11 * (1.0 - smoothstep(1.18, 1.45, uT));
334	  vec3 ep = vec3(${ENTRY_X.toFixed(4)}, ${AXIS_Y.toFixed(4)}, 0.0);
335	  float d2 = dot(p - ep, p - ep);
336	  p.x -= dentAmt * exp(-d2 / 0.045);
337	  /* curled, fast-retracting torn rim */
338	  float e = tearFront(position, uv);
339	  float c = (uT > 1.04 && e > 0.0 && e < 0.14) ? (1.0 - e / 0.14) : 0.0;
340	  p += normal * (0.055 * c);
341	  p.y += 0.11 * c * sign(uv.y - 0.5);
342	  p.x *= 1.0 - 0.22 * c;
343	  vec4 w = modelMatrix * vec4(p, 1.0);
344	  vW = w.xyz;
345	  vN = normalize(mat3(modelMatrix) * normal);
346	  gl_Position = projectionMatrix * viewMatrix * w;
347	}`;
348	
349	const latexFrag = `
350	uniform float uT;
351	uniform vec3 uColor;
352	uniform vec3 uKeyDir;
353	uniform vec3 uRim1Dir;
354	uniform vec3 uRim2Dir;
355	varying vec3 vN;
356	varying vec3 vW;
357	varying vec3 vP0;
358	varying vec2 vUv;
359	void main() {
360	  float ang = atan(vP0.z, vP0.x);
361	  float dAng = abs(atan(sin(ang), cos(ang)));
362	  float prog = smoothstep(1.04, 1.60, uT) * 1.14;
363	  float front = max(dAng / 3.14159265, abs(vUv.y - 0.5) / 0.5);
364	  front += (0.05 * sin(ang * 21.0 + vUv.y * 55.0) + 0.035 * sin(vUv.y * 83.0 + ang * 7.0)) * (0.3 + 0.7 * prog);
365	  float e = front - prog;
366	  if (uT > 1.04 && e < 0.0) discard;
367	  float c = (uT > 1.04 && e < 0.14) ? (1.0 - e / 0.14) : 0.0;
368	
369	  vec3 N = normalize(vN);
370	  if (!gl_FrontFacing) N = -N;
371	  vec3 V = normalize(cameraPosition - vW);
372	  vec3 H1 = normalize(uKeyDir + V);
373	  vec3 H2 = normalize(uRim1Dir + V);
374	  vec3 H3 = normalize(uRim2Dir + V);
375	
376	  float diff = max(dot(N, uKeyDir), 0.0) * 0.95
377	             + max(dot(N, uRim1Dir), 0.0) * 0.50
378	             + max(dot(N, uRim2Dir), 0.0) * 0.32;
379	  float spec = pow(max(dot(N, H1), 0.0), 140.0) * 1.25
380	             + pow(max(dot(N, H2), 0.0), 90.0) * 1.05
381	             + pow(max(dot(N, H3), 0.0), 70.0) * 0.55;
382	  float fres = pow(1.0 - max(dot(N, V), 0.0), 3.0);
383	  float trans = pow(max(dot(V, -uKeyDir), 0.0), 3.0);
384	
385	  vec3 col = uColor * (0.24 + diff * 0.95);
386	  col += vec3(1.0, 0.97, 0.9) * spec;
387	  col += vec3(0.85, 0.93, 1.0) * fres * 0.50;
388	  col += uColor * fres * 0.85;
389	  col += uColor * trans * 0.65;
390	  col += vec3(1.0, 0.85, 0.8) * c * 0.9;   /* wet glistening tear edge */
391	  float alpha = clamp(0.80 + 0.20 * fres + 0.15 * c, 0.0, 1.0);
392	  gl_FragColor = vec4(col, alpha);
393	  #include <encodings_fragment>
394	}`;
395	
396	const latexGeo = new THREE.LatheGeometry(makeProfilePoints(1, 1, 72), 96);
397	const latexMat = new THREE.ShaderMaterial({
398	  uniforms: latexUniforms,
399	  vertexShader: latexVert,
400	  fragmentShader: latexFrag,
401	  transparent: true,
402	  depthWrite: true,
403	  side: THREE.DoubleSide
404	});
405	const latex = new THREE.Mesh(latexGeo, latexMat);
406	latex.renderOrder = 2;
407	scene.add(latex);
408	
409	/* knot at the neck */
